export const main = (): i32 => {
  const t: Suite = new Suite("rfc6234-sha");
  let ran: string = "";
  ran = `${ran}${clause_SHA_384_1(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_384_2(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_384_4(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_384_6(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_384_8(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_384_10(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_512_1(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_512_2(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_512_4(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_512_6(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_512_8(t) ? "1" : "0"}`;
  ran = `${ran}${clause_SHA_512_10(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_LEN_512(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_LEN_384(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_LEN_ALL(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_384_IV(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_CHUNK(t) ? "1" : "0"}`;
  const code: i32 = t.done();
  const nonce: string = toI32(process.argv.length) > 1 ? process.argv[1] : "-";
  console.log(`vector-done ${nonce} ${ran}`);
  return code;
};
